        Stack<Integer> st = new Stack<>();
        int secondMax = Integer.MIN_VALUE;

        for (int x = n - 1; x >= 0; x--) {
            if (nums[x] < secondMax)
                return true;

            while (!st.isEmpty() && st.peek() < nums[x])
                secondMax = Math.max(st.pop(), secondMax);

            st.push(nums[x]);
        }
        return false;
    }
}

0895-maximum-frequency-stack:
class FreqStack {
    HashMap<Integer, Integer> freq = new HashMap<>();
    HashMap<Integer, Stack<Integer>> m = new HashMap<>();
    int maxfreq = 0;

    public void push(int x) {
        int f = freq.getOrDefault(x, 0) + 1;
        freq.put(x, f);
        maxfreq = Math.max(maxfreq, f);
        if (!m.containsKey(f)) m.put(f, new Stack<Integer>());
        m.get(f).add(x);
    }

    public int pop() {
        int x = m.get(maxfreq).pop();
        freq.put(x, maxfreq - 1);
        if (m.get(maxfreq).size() == 0) maxfreq--;
        return x;
    }
}

