    }

    public int[] findEdges(int mid, int[] nums, int target) {
        int left = mid;
        int right = mid;
        int[] result = {left, right};

        while (left >= 0 && nums[left] == target) {
            result[0] = left;
            left --;
        }

        while (right <= nums.length - 1 && nums[right] == target) {
            result[1] = right;
            right ++;
        }

        return result;
    }
}

