class Solution {
    public ListNode partition(ListNode head, int x) {
        ListNode head1 = new ListNode(); // will store node.value < x
        ListNode head2 = new ListNode(); // will store node.value >= x

        ListNode tail1 = head1, tail2 = head2, curr = head;

        while (curr != null) {
            if (curr.val < x) {
                tail1.next = curr;
                tail1 = tail1.next;
            } else {
                tail2.next = curr;
                tail2 = tail2.next;
            }
            curr = curr.next;
        }
        // at this point the two lists are not connected the way we want them to
        // we'll need to connect the list with values<x to list with values >= x
        // also the last node (tail2) is currently pointing to some random node but it
        // should point to null
        tail1.next = head2.next;
        tail2.next = null;
        return head1.next;
    }
}

0061-rotate-list:
//TC: O(n) + O(n- (n % k)) ~ O(n)
//SC: O(1)

class Solution {
    public ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0)
            return head;

        int l = 1; // length of list
        ListNode temp = head;

        // calculate the list's length
        while (temp.next != null) {
            l++;
            temp = temp.next;
        }

        temp.next = head; // make the list cyclic
        k = k % l; // handles the case where k>l
        k = l - k;

        while (k > 0) {
            temp = temp.next;
            k--;
        }
        head = temp.next;
        temp.next = null;

        return head;
    }
}

0092-reverse-linked-list-ii:
/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
  public ListNode reverseBetween(ListNode head, int left, int right) {

    if (head == null || head.next == null) {
      return head;
    }

    if (left > right || left == right) {
      return head;
    }

    ListNode l = head;
    ListNode prevL = null;
    ListNode r = head;
    ListNode nextR = null;
    int posL = 1;
    int posR = 1;

    while (posL != left) {
      prevL = l;
      l = l.next;
      posL++;
    }

    while (posR != right) {
      r = r.next;
      posR++;
    }

    nextR = r.next;
    r.next = null;
    ListNode node = reverseList(l);
    node.next = nextR;
    if (prevL == null) {
      head = r;
    } else {
      prevL.next = r;
    }
    return head;
  }

  public ListNode reverseList(ListNode l) {
    if (l.next == null) {
      return l;
    }
    ListNode newNode = reverseList(l.next);
    newNode.next = l;
    l.next = null;
    return l;
  }
}

