class Solution {
    HashMap<Integer, List<TreeNode>> memo = new HashMap<>();
    public List<TreeNode> allPossibleFBT(int n) {
        if(n == 0)
            return new ArrayList<TreeNode>();
        if(n == 1)
            return new ArrayList<TreeNode>(Arrays.asList(new TreeNode(0)));
        if(memo.containsKey(n))
            return memo.get(n);

        List<TreeNode> res = new ArrayList<>();
        for(int l = 0; l < n; l++){
            int r = n-1-l;
            List<TreeNode> leftTree = allPossibleFBT(l);
            List<TreeNode> rightTree = allPossibleFBT(r);

            for(TreeNode t1 : leftTree){
                for(TreeNode t2 : rightTree){
                    res.add(new TreeNode(0, t1, t2));
                }
            }
        }
        memo.put(n, res);
        return res;            
    }
}

0513-find-bottom-left-tree-value:
class Solution {

    static class pair {
        TreeNode node;
        int level;
        pair(TreeNode node, int level) {
            this.node = node;
            this.level = level;
        }
    }

    public static int findBottomLeftValue(TreeNode root) {
        Queue<pair> q = new ArrayDeque<>();
        q.add(new pair(root, 0));
        pair ans = new pair(root, 0);
        while (!q.isEmpty()) {
            pair current = q.poll();
            TreeNode currentNode = current.node;
            int currentLevel = current.level;
            if (currentNode.left != null) q.add(new pair(currentNode.left, currentLevel + 1));
            if (currentNode.right != null) q.add(new pair(currentNode.right, currentLevel + 1));
            if (ans.level < currentLevel) ans = current;
        }
        return ans.node.val;
    }
}

