// Recursive solution
class Solution {
    private int curSum = 0;

    public TreeNode convertBST(TreeNode root) {
         convertBSTRecursive(root);
         return root;
    }

    private void convertBSTRecursive(TreeNode node) {
        if (node == null) {
            return;
        }

        convertBSTRecursive(node.right);
        int temp = node.val;
        node.val += curSum;
        curSum += temp;
        convertBSTRecursive(node.left);
    }
}

// Iterative solution
class Solution {
    public TreeNode convertBST(TreeNode root) {
        Stack<TreeNode> stack = new Stack<>();
        TreeNode cur = root;

        int curSum = 0;
        while (cur != null || !stack.isEmpty()) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.right;
            }
            cur = stack.pop();
            cur.val += curSum;
            curSum = cur.val;
            cur = cur.left;
        }

        return root;
    }
}

0124-binary-tree-maximum-path-sum:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {

    public int maxPathSum(TreeNode root) {
        int[] res = { Integer.MIN_VALUE };
        maxPathSum(root, res);
        return res[0];
    }

    public int maxPathSum(TreeNode root, int[] res) {
        if (root == null) return 0;

        int left = Math.max(0, maxPathSum(root.left, res));
        int right = Math.max(0, maxPathSum(root.right, res));
        res[0] = Math.max(res[0], root.val + left + right);

        return root.val + Math.max(left, right);
    }
}

