0502-ipo:
class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        // Max-heap for profits of affordable projects
        Queue<Integer> maxProfit = new PriorityQueue<>(Comparator.reverseOrder());

        // Min-heap for (capital, profit) pairs
        Queue<int[]> minCapital = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        for (int i = 0; i < capital.length; i++) {
            minCapital.add(new int[] { capital[i], profits[i] });
        }

        for (int i = 0; i < k; i++) {
            // Add all affordable projects to the maxProfit heap
            while (!minCapital.isEmpty() && minCapital.peek()[0] <= w) {
                int[] project = minCapital.poll();
                maxProfit.add(project[1]);
            }

            // If there are no affordable projects, break
            if (maxProfit.isEmpty()) {
                break;
            }

            // Select the project with the maximum profit
            w += maxProfit.poll();
        }

        return w;
    }
}

0078-subsets:
// The idea is to have two conditions: 
// One in which we will take the element into consideration, 
// Second in which we won't take the element into consideration.
class Solution {

    public List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> ans = new ArrayList<>();
        List<Integer> list = new ArrayList<>();
        helper(ans, 0, nums, list);
        return ans;
    }

    public void helper(
        List<List<Integer>> ans,
        int start,
        int[] nums,
        List<Integer> list
    ) {
        if (start >= nums.length) {
            ans.add(new ArrayList<>(list));
        } else {
            // add the element and start the  recursive call
            list.add(nums[start]);
            helper(ans, start + 1, nums, list);
            // remove the element and do the backtracking call.
            list.remove(list.size() - 1);
            helper(ans, start + 1, nums, list);
        }
    }
}

