import java.util.Map;

class Solution {

    private Map<Character, String> digitToChar = Map.of(
        '2',
        "abc",
        '3',
        "def",
        '4',
        "ghi",
        '5',
        "jkl",
        '6',
        "mno",
        '7',
        "pqrs",
        '8',
        "tuv",
        '9',
        "wxyz"
    );

    public List<String> letterCombinations(String digits) {
        if (digits.length() == 0) {
            return new ArrayList();
        }

        List<String> ans = new ArrayList();
        String cur = "";
        backtrack(digits, ans, cur, 0);
        return ans;
    }

    public void backtrack(
        String digits,
        List<String> ans,
        String cur,
        int index
    ) {
        if (cur.length() == digits.length()) {
            ans.add(cur);
            return;
        } else if (index >= digits.length()) {
            return;
        } else {
            String digit = digitToChar.get(digits.charAt(index));
            for (char c : digit.toCharArray()) {
                backtrack(digits, ans, cur + c, index + 1);
            }
        }
    }
}

0473-matchsticks-to-square:
class Solution {
    boolean[] used;
    public boolean makesquare(int[] matchsticks) {
        used = new boolean[matchsticks.length];
        int total = 0;
        for (int n : matchsticks) {
            total += n;
        }
        //Check if total of all the sides is divisible by 4 or not
        if (total % 4 != 0) return false;
        int side = total / 4;

        return helper(matchsticks, side, 0, 0, 4);
    }

    boolean helper(int[] matchsticks, int targetSide, int currentSum, int index, int sides) {
        //if all the sides are matching the target side length then we found a solution
        if (sides == 0)
            return true;
        //Check if current side is equal to targetSide , that means we found another side
        if (currentSum == targetSide) {
            return helper(matchsticks, targetSide, 0, 0, sides - 1);
        }

        for (int i = index; i < matchsticks.length; i++) {
            //Only use matchsticks which are not used and which doesn't increase the current side more than target side
            if (!used[i] && currentSum + matchsticks[i] <= targetSide) {
                used[i] = true;
                boolean found = helper(matchsticks, targetSide, currentSum + matchsticks[i], i + 1, sides);
                if (found) {
                    return true;
                }
                used[i] = false;
            }
        }
        return false;
    }


}

1849-splitting-a-string-into-descending-:
import java.math.BigInteger;

class Solution {
    public boolean splitString(String s) {
        for (int i = 0; i < s.length() - 1; i++) {
            BigInteger curValue = new BigInteger(s.substring(0, i + 1));
            if (backtrack(i + 1, s, curValue)) {
                return true;
            }
        }

        return false;
    }

    private boolean backtrack(int startIndex,
                              String s,
                              BigInteger lastValue) {
        if (startIndex >= s.length()) {
            return true;
        }

        for (int i = startIndex; i < s.length(); i++) {
            BigInteger curValue = new BigInteger(s.substring(startIndex, i + 1));
            if (lastValue.subtract(curValue).compareTo(BigInteger.ONE) == 0 &&
                    backtrack(i + 1, s, curValue)) {
                return true;
            }
        }

        return false;
    }
}

1980-find-unique-binary-string:
class Solution {
    /**
     * If k is the length of the String and there are n Strings
     * Time Complexity = O(2^k)
     * Space Complexity = n*k (for set) + k (for the current sequence)
     */
    public String findDifferentBinaryString(String[] nums) {
        Set<String> uniqueNums = Set.of(nums);
        return helper(uniqueNums, uniqueNums.size(), new StringBuffer());
    }

    String helper(Set<String> uniqueStr, int size, StringBuffer currentSeq) {
        //Check if current sequence has reached to required length
        if (currentSeq.length() == size) {
            //Check if current sequence exists in the provided list , we can keep track of it as global flag too
            if (!uniqueStr.contains(currentSeq.toString())) {
                return currentSeq.toString();
            }
            //current sequence is not unique
            return null;
        }

        //Only if current sequence length is smaller than required length
        currentSeq.append("0");
        String result = helper(uniqueStr, size, currentSeq);
        currentSeq.deleteCharAt(currentSeq.length() - 1);

        //Check if we can find an ans with "0"
        if (result != null) {
            return result;
        }
        //If appending "0" didn't work then try with "1"
        currentSeq.append("1");
        result = helper(uniqueStr, size, currentSeq);
        currentSeq.deleteCharAt(currentSeq.length() - 1);

        return result;
    }
}

0698-partition-to-k-equal-sum-subsets:
class Solution {
    int target;

    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        for(int n : nums){
            sum += n;
        }
        if(sum%k != 0)
            return false;

        target = sum / k;
        boolean[] used = new boolean[nums.length];
        return backtrack(nums, 0, k, 0, used);
    }

    private boolean backtrack(int[] nums, int i, int k, int subsetSum, boolean[] used){
        if(k == 0)
            return true;
        if(subsetSum == target)
            return backtrack(nums, 0, k-1, 0, used);

        for(int j = i; j < nums.length; j++){
            if(j > 0 && !used[j-1] && nums[j] == nums[j-1])
                continue;
            if(used[j] || subsetSum + nums[j] > target)
                continue;

            used[j] = true;
            if(backtrack(nums, j+1, k, subsetSum + nums[j], used))
                return true;

            used[j] = false;        
        }
        return false;        
    }
}

0051-n-queens:
// Solution 1:
class Solution {

    public List<List<String>> solveNQueens(int n) {
        List<List<String>> ans = new ArrayList<List<String>>();
        boolean[][] board = new boolean[n][n];
        queens(board, 0, ans);
        return ans;
    }

    public void queens(boolean[][] board, int row, List<List<String>> ans2) {
        //base case
        if (row == board.length) {
            ArrayList<String> ans = new ArrayList<String>();
            createAnswer(board, ans);
            ans2.add(ans);
            return;
        }
        for (int col = 0; col < board.length; col++) {
            if (isSafe(board, row, col)) {
                board[row][col] = true;
                queens(board, row + 1, ans2);
                board[row][col] = false;
            }
        }
    }

    public void createAnswer(boolean[][] board, ArrayList<String> ans) {
        for (int i = 0; i < board.length; i++) {
            StringBuilder str = new StringBuilder();
            for (int j = 0; j < board[0].length; j++) {
                if (board[i][j]) {
                    str.append("Q");
                } else str.append(".");
            }
            ans.add(str.toString());
        }
    }

    public boolean isSafe(boolean[][] board, int row, int col) {
        for (int i = 0; i < row; i++) {
            if (board[i][col]) {
                return false;
            }
        }
        int maxLeft = Math.min(row, col);
        for (int i = 1; i <= maxLeft; i++) {
            if (board[row - i][col - i]) {
                return false;
            }
        }
        int maxRight = Math.min(row, board.length - 1 - col);
        for (int i = 1; i <= maxRight; i++) {
            if (board[row - i][col + i]) return false;
        }
        return true;
    }
}



// Solution 2:
/*
 * This solution uses 3 hashsets to check whether the current queen has conflicts with previous
 * columns and two diagonals, avoiding the use of 2D boolean array and the isSafe checking function.
 * 
 */
class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        List<String> cur = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        Set<Integer> leftSet = new HashSet<>(); // diag \ row - col
        Set<Integer> rightSet = new HashSet<>(); // diag / row + col
        Set<Integer> colSet = new HashSet<>(); // column | col
        dfs(n, result, cur, leftSet, rightSet, colSet);
        return result;
    }

    private void dfs(int n, List<List<String>> result, List<String> cur, Set<Integer> leftSet,
            Set<Integer> rightSet, Set<Integer> colSet) {
        if (cur.size() == n) {
            result.add(new ArrayList(cur));
            return;
        }
        int row = cur.size();
        // i is column index
        for (int i = 0; i < n; i++) {
            if (leftSet.contains(row - i) || rightSet.contains(row + i) || colSet.contains(i)) {
                continue;
            }
            // current col index is added to the solution list cur
            cur.add(convert(n, i));
            leftSet.add(row - i);
            rightSet.add(row + i);
            colSet.add(i);
            // go to dfs next level
            dfs(n, result, cur, leftSet, rightSet, colSet);
            // backtracking
            cur.remove(cur.size() - 1);
            leftSet.remove(row - i);
            rightSet.remove(row + i);
            colSet.remove(i);

        }
    }

    private String convert(int n, int col) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i == col) {
                res.append("Q");
            } else {
                res.append(".");
            }
        }
        return res.toString();
    }
}

0052-n-queens-ii:
class Solution {
    int count = 0;

    public int totalNQueens(int n) {
        Set<Integer> colSet = new HashSet<>();
        Set<Integer> posDiagSet = new HashSet<>(); // (r + c)
        Set<Integer> negDiagSet = new HashSet<>(); // (r - c)
        backtrack(0, n, colSet, posDiagSet, negDiagSet);
        return count;
    }

    private void backtrack(
            int row,
            int n,
            Set<Integer> colSet,
            Set<Integer> posDiagSet,
            Set<Integer> negDiagSet) {
        if (row == n) {
            count += 1;
            return;
        }

        for (int col = 0; col < n; col++) {
            if (colSet.contains(col)
                    || posDiagSet.contains(row + col)
                    || negDiagSet.contains(row - col)) {
                continue;
            }
            colSet.add(col);
            posDiagSet.add(row + col);
            negDiagSet.add(row - col);
            backtrack(row + 1, n, colSet, posDiagSet, negDiagSet);
            colSet.remove(col);
            posDiagSet.remove(row + col);
            negDiagSet.remove(row - col);
        }
    }
}

0463-island-perimeter:
class Solution {
    class RecursiveBiFunction<A, B, C> {
        BiFunction<A, B, C> func;
    }

    public int islandPerimeter(int[][] _grid) {
        final int[][] grid = _grid;
        final Set<Integer> visit = new HashSet<>();

        final RecursiveBiFunction<Integer, Integer, Integer> dfs = new RecursiveBiFunction();
        dfs.func = (i, j) -> {
            if(i >= grid.length || j >= grid[0].length || i < 0 || j < 0 || grid[i][j] == 0)
                return 1;
            //convert 2D-Coordinate to 1D-Coordinate
            int flatCoord = i*grid[0].length + j;
            if(visit.contains(flatCoord))
                return 0;

            visit.add(flatCoord);
            int perim = dfs.func.apply(i, j + 1);
            perim += dfs.func.apply(i + 1, j);
            perim += dfs.func.apply(i, j - 1);
            perim += dfs.func.apply(i - 1, j);
            return perim;
        };

        for(int i = 0; i < grid.length; i++)
            for(int j = 0; j < grid[0].length; j++)
                if(grid[i][j] != 0)
                    return dfs.func.apply(i, j);
        return -1;
    }
}

