class Solution {

    public List<String> findItinerary(List<List<String>> tickets) {
        LinkedList<String> itinerary = new LinkedList<>();
        Map<String, PriorityQueue<String>> graph = new HashMap<>();
        Stack<String> stack = new Stack<>();

        for (List<String> ticket : tickets) {
            graph
                .computeIfAbsent(ticket.get(0), k -> new PriorityQueue<>())
                .add(ticket.get(1));
        }

        stack.push("JFK");
        while (!stack.isEmpty()) {
            String nextDestination = stack.peek();

            if (
                !graph
                    .getOrDefault(nextDestination, new PriorityQueue<>())
                    .isEmpty()
            ) {
                stack.push(graph.get(nextDestination).poll());
            } else {
                itinerary.addFirst(stack.pop());
            }
        }
        return itinerary;
    }
}

1584-min-cost-to-connect-all-points:
class Solution {

    // Time Complexity: O(N^2 log(N)) where N is the length of points. N^2 comes from the fact we need to find the distance between a currNode and every other node to pick the shortest distance. log(N) comes from Priority Queue
    // Space Complexity: O(N^2)
    public int minCostConnectPoints(int[][] points) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]); // edge weight, the index of next node
        pq.offer(new int[] { 0, 0 });
        int len = points.length;
        Set<Integer> visited = new HashSet<>();
        int cost = 0;

        // When visited.size() == points.len meaning that all the nodes has been connected.
        while (visited.size() < len) {
            int[] arr = pq.poll();

            int weight = arr[0];
            int currNode = arr[1];

            if (visited.contains(currNode)) continue;

            visited.add(currNode);
            cost += weight;

            for (int nextNode = 0; nextNode < len; nextNode++) {
                if (!visited.contains(nextNode)) {
                    int nextWeight =
                        Math.abs(points[nextNode][0] - points[currNode][0]) +
                        Math.abs(points[nextNode][1] - points[currNode][1]);
                    pq.offer(new int[] { nextWeight, nextNode });
                }
            }
        }

        return cost;
    }
}

0743-network-delay-time:
// Bellman Ford ALgorithm
// Time Complexty (n * t) | Space Complexity O(n) where t is the length of times
class Solution {

    public int networkDelayTime(int[][] times, int n, int k) {
        // initialize an array with max value of size n
        int[] paths = new int[n];
        Arrays.fill(paths, Integer.MAX_VALUE);

        paths[k - 1] = 0;

        for (int i = 0; i < n; i++) {
            // make a copy of paths
            int[] temp = new int[n];
            temp = Arrays.copyOf(paths, paths.length);

            // loop through times
            for (int j = 0; j < times.length; j++) {
                int src = times[j][0]; // source
                int tgt = times[j][1]; // target
                int time = times[j][2]; // time

                if (
                    temp[src - 1] != Integer.MAX_VALUE &&
                    temp[src - 1] + time < temp[tgt - 1]
                ) {
                    temp[tgt - 1] = temp[src - 1] + time;
                }
            }

            // set paths to temp
            paths = temp;
        }

        int result = Integer.MIN_VALUE;

        // calculate max value
        for (int i = 0; i < n; i++) {
            if (paths[i] == Integer.MAX_VALUE) {
                return -1;
            }
            result = Math.max(result, paths[i]);
        }

        // return result
        return result;
    }
}

1514-path-with-maximum-probability:
class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        // create the graph
        List<double[]>[] graph = new LinkedList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new LinkedList<>();
        }

        for (int i = 0; i < edges.length; i++) {
            double from =  edges[i][0];
            double to =  edges[i][1];
            double weight = succProb[i];
            double[] m = new double[2];
            m[0] = to;
            m[1] = weight;
            graph[edges[i][0]].add(m);
            double[] k = new double[2];
            k[0] = from;
            k[1] = weight;
            graph[edges[i][1]].add(k);
        }

        // call dijkstra and return 
        return dijkstra(start, end, graph);
    }

    class State{
        int id;
        double proToStart;

        public State(int id, double proToStart){
            this.id = id;
            this.proToStart = proToStart;
        }
    }

    private double dijkstra(int start, int end, List<double[]>[] graph){
        double[] proTo = new double[graph.length];
        // 初始化为一个去不到的值
        Arrays.fill(proTo, -1);
        proTo[start] = 1;

        PriorityQueue<State> pq = new PriorityQueue<State>((a, b) -> {
        return Double.compare(b.proToStart, a.proToStart);
    });
        pq.offer(new State(start, 1));

        while (!pq.isEmpty()){
            State cur = pq.poll();
            int curid = cur.id;
            double curproToStart = cur.proToStart;

            if (curid == end) {
                return curproToStart;
            }

            if (proTo[curid] > curproToStart) {
                continue;
            }

            List<double[]> nexts = graph[curid];
            for (double[] next: nexts) {
                double proToNext = proTo[curid] * next[1];
                int idx = (int) next[0];
                if (proToNext > proTo[idx]) {
                    proTo[idx] = proToNext;
                    pq.offer(new State(idx, proToNext));
                }
            }
        }

        return 0;
    }
}

0778-swim-in-rising-water:
// Solution: Greedy Approach with Min Heap
// Time Complexity: O((n^2)*log(n))
class Solution {

    private int[][] dirs = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };

    public int swimInWater(int[][] grid) {
        int len = grid.length;

        if (len == 1) {
            return 0;
        }

        var seen = new boolean[len][len];
        seen[0][0] = true;

        var minHeap = new PriorityQueue<Integer[]>((a, b) -> a[0] - b[0]);
        minHeap.add(new Integer[] { grid[0][0], 0, 0 });

        int result = 0;

        while (!minHeap.isEmpty()) {
            var curr = minHeap.poll();

            result = Math.max(result, curr[0]);

            if (curr[1] == len - 1 && curr[2] == len - 1) {
                break;
            }

            for (int i = 0; i < 4; i++) {
                int x = curr[1] + dirs[i][0];
                int y = curr[2] + dirs[i][1];

                if (x < 0 || x >= len || y < 0 || y >= len || seen[x][y]) {
                    continue;
                }

                minHeap.add(new Integer[] { grid[x][y], x, y });
                seen[x][y] = true;
            }
        }

        return result;
    }
}

0269-alien-dictionary:
class Solution {

    Map<Character, Set<Character>> adjList;
    Map<Character, Set<Character>> revList;
    Map<Character, Integer> degrees;

    // Return false if s.len < t.len condition is not met
    private boolean createEdges(String left, String right) {
        int minLen = Math.min(left.length(), right.length());

        for (int i = 0; i < minLen; i++) {
            char first = left.charAt(i), second = right.charAt(i);

            if (first != second) {
                Set<Character> edges = this.adjList.get(first);
                edges.add(second);
                this.adjList.put(first, edges);

                Set<Character> revEdges = this.revList.get(second);
                revEdges.add(first);
                this.revList.put(second, revEdges);

                return true;
            }
        }

        // No difference found yet, there is a problem
        return (left.length() <= right.length());
    }

    private void initialize(String[] words) {
        // Initialize
        int n = words.length;
        this.adjList = new HashMap<>();
        this.revList = new HashMap<>();
        this.degrees = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (char c : words[i].toCharArray()) {
                this.adjList.put(c, new HashSet<>());
                this.revList.put(c, new HashSet<>());
                this.degrees.put(c, 0);
            }
        }
    }

    // Return false if creating any edge leads to a problem
    private boolean createEdges(String[] words) {
        int n = words.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                if (createEdges(words[i], words[j]) == false) return false;
            }
        }
        return true;
    }

    private void createDegrees() {
        for (char c : this.adjList.keySet()) {
            this.degrees.put(c, this.adjList.get(c).size());
        }
    }

    private List<Character> topologicalSort() {
        // take zero degrees first into a queue
        Queue<Character> queue = new LinkedList<>();

        Set<Character> taken = new HashSet<>();
        List<Character> ordering = new ArrayList<>();

        for (char c : this.degrees.keySet()) {
            if (this.degrees.get(c) == 0) {
                queue.add(c);
            }
        }

        // Case 1: Doesn't exist
        if (queue.isEmpty()) {
            return null;
        }

        while (!queue.isEmpty()) {
            int qSize = queue.size();

            // Level order traversal
            for (int i = 0; i < qSize; i++) {
                char removed = queue.remove();

                // Put into the ordering
                ordering.add(removed);
                taken.add(removed);

                // In the reverse list, need to decrement for all neighbors, and if any is zero, need to put into the queue
                for (char neighbor : this.revList.get(removed)) {
                    int degree = this.degrees.get(neighbor);
                    degree--;

                    if (degree == 0) queue.add(neighbor); // add to queue

                    this.degrees.put(neighbor, degree);
                }
            }
        }

        // Case 2: Not all vertices were ordered
        if (ordering.size() < this.revList.size()) {
            return null;
        }

        return ordering;
    }

    private String getString(List<Character> ordering) {
        StringBuilder bld = new StringBuilder();
        for (char c : ordering) bld.append(c);
        return bld.reverse().toString();
    }

    // API
    public String alienOrder(String[] words) {
        initialize(words);

        // Edge case, s.len < t.len is not met
        if (createEdges(words) == false) return "";

        createDegrees();

        List<Character> ordering = topologicalSort();

        if (ordering == null) return "";

        return getString(ordering);
    }
}

0787-cheapest-flights-within-k-stops:
// Time Complexity O(k * n) | Space Complexity O(n)
class Solution {

    public int findCheapestPrice(
        int n,
        int[][] flights,
        int src,
        int dst,
        int k
    ) {
        // initialize an array with max value of size n
        int[] prices = new int[n];
        Arrays.fill(prices, Integer.MAX_VALUE);

        // price from source to source is always 0
        prices[src] = 0;

        for (int i = 0; i <= k; i++) {
            // make a copy of prices
            int[] temp = new int[n];
            temp = Arrays.copyOf(prices, prices.length);

            // loop through flights
            for (int j = 0; j < flights.length; j++) {
                int s = flights[j][0]; // from
                int d = flights[j][1]; // to
                int p = flights[j][2]; // price

                if (prices[s] == Integer.MAX_VALUE) {
                    continue;
                }

                if (prices[s] + p < temp[d]) {
                    temp[d] = prices[s] + p;
                }
            }

            // set prices to temp
            prices = temp;
        }

        if (prices[dst] != Integer.MAX_VALUE) {
            return prices[dst];
        }

        return -1;
    }
}

