            int maxAge = pairs[i][1];
            for (int j = 0; j < i; j++) {
                int score = pairs[j][0];
                int age = pairs[j][1];
                if (maxAge >= age) {
                    dp[i] = Math.max(dp[i], maxScore + dp[j]);
                }
            }
        }

        return Arrays.stream(dp).max().getAsInt();
    }
}

