/*          Top Down Approach
-----------------------------------------
    Time Complexity : O(n)
    Space Complexity : O(n)
----------------------------------------*/

class Solution {
    HashMap<String, Integer> memo = new HashMap<>();
    int MOD = (int) 1e9 + 7; 

    public int countVowelPermutation(int n) {
        long ans = 0;
        ans = (ans + dfs('a', n, 1)) % MOD;
        ans = (ans + dfs('e', n, 1)) % MOD;
        ans = (ans + dfs('i', n, 1)) % MOD;
        ans = (ans + dfs('o', n, 1)) % MOD;
        ans = (ans + dfs('u', n, 1)) % MOD;
        return (int)ans;
    }

    private int dfs(char c, int n, int l){
        if(l == n)
            return 1;

        String key = c + "_" + l;
        if (memo.containsKey(key)) return memo.get(key);

        long res = 0;
        if (c == 'a') {
            res = dfs('e', n, l + 1);
        } else if (c == 'e') {
            res = (res + dfs('a', n, l + 1)) % MOD;
            res = (res + dfs('i', n, l + 1)) % MOD;
        } else if (c == 'i') {
            res = (res + dfs('a', n, l + 1)) % MOD;
            res = (res + dfs('e', n, l + 1)) % MOD;
            res = (res + dfs('o', n, l + 1)) % MOD;
            res = (res + dfs('u', n, l + 1)) % MOD;
        } else if (c == 'o') {
            res = (res + dfs('i', n, l + 1)) % MOD;
            res = (res + dfs('u', n, l + 1)) % MOD;
        } else {
            res = dfs('a', n, l + 1);
        }

        memo.put(key, (int)(res % MOD));
        return (int)(res % MOD);    
    }
}

0312-burst-balloons:
// Solution: Dynamic Programming with Memoization

// Time Complexity: O(n^3)
// Extra Space Complexity: O(n^2)
class Solution {

    public int maxCoins(int[] nums) {
        var dp = new int[nums.length][nums.length];

        return burst(nums, 0, nums.length - 1, dp);
    }

    private int burst(int[] nums, int left, int right, int[][] dp) {
        if (left > right) {
            return 0;
        }
        if (dp[left][right] != 0) {
            return dp[left][right];
        }

        for (int i = left; i <= right; i++) {
            int coins = nums[i];

            if (left - 1 >= 0) {
                coins *= nums[left - 1];
            }
            if (right + 1 < nums.length) {
                coins *= nums[right + 1];
            }

            coins +=
                burst(nums, left, i - 1, dp) + burst(nums, i + 1, right, dp);
            dp[left][right] = Math.max(dp[left][right], coins);
        }

        return dp[left][right];
    }
}

