class Solution {

    public boolean isMatch(String s, String p) {
        boolean[][] cache = new boolean[s.length() + 1][p.length() + 1];

        return dfs(cache, s, p, 0, 0);
    }

    private boolean dfs(boolean[][] cache, String s, String p, int i, int j) {
        if (cache[i][j] != false) return cache[i][j];

        if (i >= s.length() && j >= p.length()) return true;

        if (j >= p.length()) return false;

        boolean match =
            i < s.length() &&
            (s.charAt(i) == p.charAt(j) || p.charAt(j) == '.');

        if (j + 1 < p.length() && p.charAt(j + 1) == '*') {
            cache[i][j] =
                dfs(cache, s, p, i, j + 2) ||
                (match && dfs(cache, s, p, i + 1, j));
        } else {
            cache[i][j] = match && dfs(cache, s, p, i + 1, j + 1);
        }

        return cache[i][j];
    }
}

1140-stone-game-ii:
class Solution {
    public int stoneGameII(int[] piles) {
        Integer[][][] dp = new Integer[2][piles.length + 1][piles.length + 1];
        return dfs(piles, 0, 0, 1, dp);
    }

    private int dfs(int[] piles, int alice, int i, int M, Integer[][][] dp) {
        if (i == piles.length) {
            return 0;
        }
        if (dp[alice][i][M] != null) {
            return dp[alice][i][M];
        }
        int res = (alice == 0) ? 0 : Integer.MAX_VALUE;
        int total = 0;
        for (int X = 1; X < 2 * M + 1; X++) {
            if (i + X > piles.length) {
                break;
            }
            total += piles[i + X - 1];
            int recurRes = dfs(piles, 1 - alice, i + X, Math.max(X, M), dp);
            if (alice == 0) {
                res = Math.max(res, total + recurRes);
            } else {
                res = Math.min(res, recurRes);
            }
        }
        dp[alice][i][M] = res;
        return res;
    }
}

0920-number-of-music-playlists:
class Solution {
    public int numMusicPlaylists(int n, int goal, int k) {
        map = new HashMap<>();
        return (int)findPlaylists(0, goal, n, k);
    }

    HashMap<Pair, Integer> map;
    int mod = 1000000007;

    public long findPlaylists(int old_songs, int goal, int n, int k) {
        if(goal == 0 && old_songs == n) {
            return 1;
        }

        if(goal == 0 || old_songs > n) {
            return 0;
        }

        if(map.containsKey(new Pair(old_songs, goal))) {
            return map.get(new Pair(old_songs, goal));
        }

        // chossing an new_song
        long res = ((n - old_songs) * (findPlaylists(old_songs + 1, goal - 1, n, k) % mod)) % mod;

        // choose an old_songs
        if(old_songs > k) {
            res = (res + ((old_songs - k) * (findPlaylists(old_songs, goal - 1, n, k)) % mod) % mod) % mod;
        }

        map.put(new Pair(old_songs, goal), (int)res);

        return res;
    }

    class Pair {
        int a;
        int b;

        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Pair pair = (Pair) obj;
            return a == pair.a && b == pair.b;
        }

        @Override
        public int hashCode() {
            return 31 * a + b;
        }
    }
}

