    public List<List<Integer>> shiftGrid(int[][] grid, int k) {
        final int M = grid.length, N = grid[0].length;

        BiFunction<Integer, Integer, Integer> posToVal = (r, c) ->
            r * N + c;
        Function<Integer, int[]> valToPos = (v) ->
