            for(int c = 0; c < N; c++) {
                int newVal = (posToVal.apply(r, c) + k) % (M * N);
                int[] newRC = valToPos.apply(newVal);
                res.get(newRC[ROW]).set(newRC[COL], grid[r][c]);
            }
        return res;
    }
}

