            if (
                matrix[curRow][curCol] != null &&
                matrix[startRow][curCol] != null &&
                matrix[curRow][startCol] != null
            ) {
                currentSquareCount =
                    currentSquareCount +
                    (
                        currentPointCount *
                        matrix[curRow][curCol] *
